#include <iostream>
#include <iomanip>
#include <cstdlib>

int main() {
    unsigned int seed = 0;
    if (!(std::cin >> seed)) {
        return 1;
    }

    // Seed the generator deterministically based on input
    std::srand(seed);

    constexpr int shiftingValue = 1;
    constexpr int scalingFactor = 6;

    // Roll a 6-sided die 10 times
    for (unsigned int counter = 1; counter <= 10; ++counter) {
        int roll = shiftingValue + std::rand() % scalingFactor;
        std::cout << std::setw(4) << roll;

        if (counter % 5 == 0) {
            std::cout << '\n';
        }
    }

    return 0;
}

#include <iostream>

// Scoped enum representing game status (C++11/C++17 style)
enum class Status { CONTINUE, WON, LOST };

int main() {
    int sumOfDice = 0;
    if (!(std::cin >> sumOfDice)) {
        return 1;
    }

    Status gameStatus = Status::CONTINUE;
    int myPoint = 0;

    // Evaluate first roll according to Craps rules
    switch (sumOfDice) {
        case 7:
        case 11:
            gameStatus = Status::WON;
            std::cout << "Player wins on first roll!\n";
            break;
        case 2:
        case 3:
        case 12:
            gameStatus = Status::LOST;
            std::cout << "Player loses (craps) on first roll!\n";
            break;
        default:
            // Point established (4, 5, 6, 8, 9, 10)
            gameStatus = Status::CONTINUE;
            myPoint = sumOfDice;
            std::cout << "Point is " << myPoint << "\n";
            break;
    }

    return 0;
}
